/* global document, location, window */
const screens={home:'01 书桌',import:'02 导入',library:'03 棋谱库',review:'04 引导复盘',moves:'05 着法',coach:'06 讲解',engine:'07 引擎',notebook:'08 笔记',complete:'09 复盘完成',practice:'10 练习',stats:'11 成长',settings:'12 设置',help:'13 帮助',share:'14 分享'};
const main=document.querySelector('#main');const picker=document.querySelector('#pages');
for(const [value,label] of Object.entries(screens)){const option=document.createElement('option');option.value=value;option.textContent=label;picker.append(option)}
picker.addEventListener('change',()=>location.hash=picker.value);
const button=(text,to,primary=false)=>`<a class="button ${primary?'primary':''}" href="#${to}">${text}</a>`;
const head=(no,title,desc,action='')=>`<div class="pagehead"><div><p class="eyebrow">${no} / BLUEBIRD STUDY</p><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const row=(title,detail,end)=>`<div class="row"><div><strong>${title}</strong><p class="muted">${detail}</p></div>${end}</div>`;
const metric=(n,label)=>`<div class="metric"><strong>${n}</strong><span>${label}</span></div>`;
const board=()=>{const ranks=['rnbqkbnr','pppppppp','........','........','....P...','........','PPPP.PPP','RNBQKBNR'];return `<div class="board" role="img" aria-label="示例棋盘，1.e4 后的位置">${ranks.flatMap((r,y)=>[...r].map((p,x)=>`<div class="square ${(x+y)%2?'dark':''}">${p!=='.'?`<img alt="" src="assets/${p===p.toUpperCase()?'w':'b'}${p.toUpperCase()}.png">`:''}</div>`)).join('')}</div>`};
const games=[['Mizore — Nozomi','意大利开局 · 32 回合','86.2%','已分析'],['Nozomi — Mizore','后翼弃兵 · 41 回合','81.4%','已分析'],['Mizore — Haruka','西西里防御 · 28 回合','—','待分析'],['Yuuko — Mizore','卡罗康防御 · 35 回合','78.0%','已分析']];
const gameList=()=>`<div class="listhead"><span>对局 / 开局</span><span>状态</span><span>准确率 · 白方</span><span>操作</span></div><div id="games">${games.map(g=>`<div class="game" data-search="${g.join(' ').toLowerCase()}"><div><strong>${g[0]}</strong><small>${g[1]}</small></div><span class="tag">${g[3]}</span><span>${g[2]}</span>${button('打开 ↗','review')}</div>`).join('')}</div><p id="noresults" hidden>没有符合条件的棋谱。</p>`;
const tabs=(active)=>`<nav class="tabs" aria-label="棋局工作区">${[['review','复盘'],['moves','着法'],['coach','讲解'],['engine','引擎'],['notebook','笔记']].map(([k,v])=>`<a href="#${k}" ${active===k?'aria-current="page"':''}>${v}</a>`).join('')}</nav>`;
const working=(type,content)=>`${head('02','Mizore — Nozomi','意大利开局 · 1–0 · 示例棋局',button('返回棋谱库','library'))}${tabs(type)}<div class="workbench"><section class="boardzone"><div class="player"><span>Nozomi · 黑方</span><span>1–0</span></div>${board()}<div class="player"><span>Mizore · 白方</span><span>1. e4</span></div><div class="transport"><span class="muted">静态棋盘 · 设计示例</span></div></section><section class="panel">${content}</section></div>`;
const panels={
review:`<div class="panelbody"><p class="eyebrow">GUIDED REVIEW / 01</p><h2>先理解一个决定。</h2><p class="muted">复盘按关键决策组织。棋盘与当前问题始终在同一个视野里。</p><div class="callout"><span class="sourcelabel">布局示例 · 非当前局面分析</span><h3>这一页只呈现一个重点</h3><p>着法评价、简短解释和下一步操作形成明确的阅读顺序。详细证据放进可展开区域。</p></div><details><summary>客观证据与评价来源</summary><p>正式版从共享分析模型读取分类、分差、PV 和证据。这里未运行引擎，不生成棋局结论。</p></details></div><div class="panelend"><span class="muted">关键时刻 1 / 5</span>${button('查看完成页 →','complete',true)}</div>`,
moves:`<div class="panelbody"><p class="eyebrow">SCORESHEET</p><h2>沿着棋谱，再走一遍。</h2><div class="moves"><span>1</span><span class="selected">e4</span><span>—</span></div><p class="muted" style="margin-top:24px">此稿以一个合法起始局面展示棋盘与着法区的关系。正式版保留方向键、变化树、走子定位及质量图标。</p><div class="callout">主线和探索分支分别标识；返回主线的入口固定在着法区顶部。</div></div><div class="panelend"><span class="muted">白方视角</span>${button('深入分析 →','engine')}</div>`,
coach:`<div class="panelbody"><p class="eyebrow">COACH / 当前着法</p><h2>解释有层次，<br>阅读有终点。</h2><p>第一层：一句话结论。第二层：与你的选择直接有关的证据。第三层：按需展开延伸内容。</p><div class="callout"><span class="sourcelabel">STOCKFISH · 客观事实</span><p>此处展示经验证的引擎评价与变化。</p></div><details><summary>Maia · 人类选择倾向</summary><p>独立呈现等级分条件与预测概率，不替代客观评价。</p></details><details><summary>AI 教练 · 基于证据的解释</summary><p>未配置服务时保留确定性解释，提供配置入口。</p></details></div><div class="panelend"><span class="muted">示例内容</span>${button('记下理解 →','notebook',true)}</div>`,
engine:`<div class="panelbody"><p class="eyebrow">ENGINE / 分析工具</p><h2>精确，也可以安静。</h2><div class="toolbar"><label>深度 <select><option>18</option><option>20</option></select></label><label>候选 <select><option>3 条</option><option>5 条</option></select></label></div><div class="empty"><p>设计预览未连接 Stockfish</p><small>正式版在此呈现分数、主变化与分析状态。</small></div><details><summary>开局数据库</summary><p>外部数据独立标明来源、样本数及请求状态。</p></details><details><summary>残局库</summary><p>满足条件时呈现已证明的结果。</p></details></div><div class="panelend"><span class="muted">本地 / 浏览器引擎</span>${button('引擎设置','settings')}</div>`,
notebook:`<div class="panelbody"><p class="eyebrow">NOTEBOOK / 当前局面</p><h2>留下自己的理解。</h2><label>笔记<textarea id="note" placeholder="这一次，我想记住……"></textarea></label><p class="muted">演示内容仅保留在此页面内存中，刷新后清除。</p></div><div class="panelend"><span id="saved" role="status">尚未记录</span><button class="primary" id="save">保存示例笔记</button></div>`};
let note='';
function render(){const requested=location.hash.slice(1);const page=Object.hasOwn(screens,requested)?requested:'home';picker.value=page;document.title=`${screens[page]} · 全平台设计预览`;
const views={
home:()=>`<section class="hero"><div><p class="eyebrow">A QUIET PLACE TO UNDERSTAND CHESS</p><h1>在每一步之间，<br>听见新的可能。</h1><p class="muted">回到一局棋，理解一个选择。<br>让下一次落子，多一点从容。</p>${button('回到我的棋局 →','review',true)}</div></section><div class="sectionline"><h2>今天，从这里开始</h2><span class="muted">YOUR STUDY DESK</span></div><div class="split"><section><div class="resume"><div class="mini">${board()}</div><div><p class="eyebrow">继续复盘</p><h3>Mizore — Nozomi</h3><p class="muted">5 个关键时刻 · 已阅读 2 个</p>${button('继续 →','review')}</div></div></section><section><p class="eyebrow">今日练习</p><h2>让理解变成直觉。</h2><p class="muted">从自己的棋局中，重新遇见那些值得思考的位置。</p>${button('查看练习 →','practice')}</section></div><div class="sectionline"><h2>最近的棋局</h2><a href="#library">全部棋谱 ↗</a></div>${gameList()}`,
import:()=>`${head('01','带来一局棋。','从棋谱开始，逐步进入复盘。')}<div class="document"><aside class="localnav"><a href="#import" aria-current="page">粘贴 PGN / FEN</a><a href="#library">查看已有棋谱 →</a><p class="muted">正式版另提供文件导入与公开账号同步。</p></aside><section class="sheet"><p class="eyebrow">01 输入 / 02 检查 / 03 开始</p><h2>粘贴棋谱</h2><label>PGN 或 FEN<textarea placeholder="[Event &quot;My game&quot;]&#10;1. e4 e5 2. Nf3 Nc6 …"></textarea></label><p class="muted">完整棋局用于整局复盘；单一局面进入引擎工作台。</p>${button('预览检查后的工作台 →','review',true)}<div class="notice">设计示例：此按钮只跳转布局预览，不会解析或保存输入。</div></section></div>`,
library:()=>`${head('02','属于你的棋谱馆。','每一局棋都有自己的位置。',button('导入棋谱 ↗','import',true))}<div class="toolbar"><input id="search" type="search" aria-label="搜索示例棋谱" placeholder="搜索棋手、开局或状态"><span class="muted">4 局示例 · 全部棋谱</span></div>${gameList()}<p class="muted" style="margin-top:20px">正式版：全部 / 待分析 / 已分析 / 有笔记，作为同一棋谱库的筛选视图。</p>`,
complete:()=>`${head('02','这一局，读完了。','把一个收获带到下一局。')}<div class="wideaction"><div><p class="eyebrow">REVIEW COMPLETE</p><h2>Mizore — Nozomi</h2><p>完成页排版示例 · 下列数字为设计样例</p></div>${button('回到棋谱库 →','library',true)}</div><div class="metrics">${metric('86.2%','白方准确率')}${metric('5','已阅读关键时刻')}${metric('2','示例收藏局面')}</div><div class="split"><section><h2>这一局的收获</h2><p>总结重点，而不是重复铺开所有统计。每条结论可以返回对应局面。</p>${button('回看关键时刻','review')}</section><section><h2>下一步，由你选择。</h2><p class="muted">保留一条笔记，或把值得重看的局面加入练习。</p>${button('写下笔记','notebook')}</section></div>`,
practice:()=>`${head('03','把理解，练成直觉。','今天的任务清楚可见，长期计划安放在下一层。')}<div class="wideaction"><div><p class="eyebrow">TODAY / 示意状态</p><h2>还没有待练习的局面</h2><p class="muted">完成第一局复盘后，把值得重看的位置加入练习。</p></div>${button('选择一局棋 →','library',true)}</div><div class="sectionline"><h2>你的训练路径</h2><span class="muted">基于已分析棋局</span></div>${row('01 · 发现问题','在复盘里找到值得重新思考的决定。',button('进入棋谱库','library'))}${row('02 · 收藏局面','保存有意义的位置与自己的理解。',button('查看笔记示例','notebook'))}${row('03 · 再次尝试','正式练习会隐藏答案，并记录实际尝试。','<span class="tag">等待加入局面</span>')}`,
stats:()=>`${head('04','看见积累的轨迹。','统计范围：示例棋谱库，非真实用户数据。')}<div class="toolbar"><span>最近 30 天</span><span class="tag">已分析棋局：3 / 4</span></div><div class="metrics">${metric('4','导入棋局')}${metric('3','完成分析')}${metric('2','带笔记的局面')}</div><div class="split"><section><h2>复盘节奏</h2><p class="muted">示意柱形 · 正式版按真实时间聚合</p><div class="diagram" role="img" aria-label="仅展示图表布局的示意柱形">${[35,56,44,68,38,83,58,95,68,78,60,100].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></section><section><h2>阅读这些数字</h2><p>导入、分析、复盘和掌握是不同阶段，需要明确各自的统计范围。</p><p class="muted">准确率不是等级分。未分析的棋局不计入准确率趋势。</p>${button('打开棋谱库 →','library')}</section></div>`,
settings:()=>`${head('05','按自己的节奏。','设置按照任务分组，一次处理一类事情。')}<div class="document"><aside class="localnav"><a href="#settings" aria-current="page">棋盘与显示</a><a href="#help">引擎与本地服务 ↗</a><a href="#help">数据与备份 ↗</a></aside><section class="sheet"><p class="eyebrow">APPEARANCE</p><h2>安静、清楚的棋盘</h2><label>棋盘主题<select><option>青瓷绿 · Bluebird</option></select></label><label>界面动态<select><option>跟随系统</option><option>减少动态</option></select></label><p class="muted">这些控件仅演示设置页布局，不会修改平台偏好。</p><div class="notice">正式版即时生效并显示保存状态；配置失败应在字段附近解释原因。</div></section></div>`,
help:()=>`${head('06','从一局棋开始。','清楚理解平台能做什么，以及数据存在哪里。')}<div class="document"><aside class="localnav"><a href="#help" aria-current="page">第一次复盘</a><a href="#settings">设置与显示 ↗</a><a href="#share">分享与导出 ↗</a></aside><article class="sheet"><h2>三步，开始理解你的棋局</h2>${row('1. 导入','使用 PGN 或 FEN。截图识别不属于导入方式。','')}${row('2. 分析','浏览器 Stockfish 提供客观评价，无需本地 AI。','')}${row('3. 理解与记录','回看关键决策，保存自己的笔记。','')}<h2>事实与解释分别呈现</h2><p>Stockfish 提供客观分析，Maia 描述人类选择倾向，AI 教练依据结构化证据解释。</p><h2>数据在你的浏览器中</h2><p>跨设备之前先备份。单独的复盘地址不等同于一份可传输的棋谱。</p>${button('导入第一局棋 →','import',true)}</article></div>`,
share:()=>`${head('07','分享一个值得记住的局面。','分享落地页与导出预览保持同一套棋局身份。')}<div class="document"><aside class="localnav"><p class="eyebrow">SHARED REVIEW</p><p class="muted">打开分享时先检查数据，再明确选择是否保存。</p></aside><section class="sheet"><h2>分享内容预览</h2><p class="muted">设计示例中未附带分享数据。</p><div class="empty"><h3>等待有效棋谱</h3><p>正式版明确区分读取中、内容有效、链接不完整和无法解析。</p></div>${button('查看棋局布局示例','review')}<div class="notice">不把示例按钮描述成真实的导入、保存或上传。</div></section></div>`};
main.classList.toggle('workpage',Boolean(panels[page]));
main.innerHTML=panels[page]?working(page,panels[page]):views[page]();
document.querySelectorAll('header nav a').forEach(a=>{const active=a.hash===`#${page}`||(a.hash==='#library'&&(panels[page]||page==='complete'));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
const search=document.querySelector('#search');if(search)search.addEventListener('input',()=>{let count=0;document.querySelectorAll('.game').forEach(el=>{el.hidden=!el.dataset.search.includes(search.value.toLowerCase());el.style.display=el.hidden?'none':'';if(!el.hidden)count++});document.querySelector('#noresults').hidden=count>0});
if(page==='notebook'){document.querySelector('#note').value=note;document.querySelector('#save').addEventListener('click',()=>{note=document.querySelector('#note').value;document.querySelector('#saved').textContent='已记录在本次设计预览中'});}
window.scrollTo(0,0);main.focus({preventScroll:true});}
window.addEventListener('hashchange',render);render();
